create schema if not exists connectify authorization postgres;

create table connectify.categories (id bigint generated by default as identity primary key, active boolean not null, description varchar(255), icon varchar(255), name varchar(255) not null unique);
create table connectify.users (id bigint generated by default as identity primary key, email varchar(255) not null unique, full_name varchar(100) not null, password varchar(255), role varchar(255), active boolean, address varchar(500), avatar_url varchar(500), bio varchar(1000), city varchar(100), company_name varchar(200), country varchar(100), created_at timestamp(6) not null, developer_key varchar(500), document_number varchar(50), enabled boolean, is_developer boolean, last_login timestamp(6), phone_number varchar(20), updated_at timestamp(6), verification_token varchar(500), verified boolean);
create table connectify.user_accounts (id bigint generated by default as identity primary key, active boolean not null, company_name varchar(255), credential_hash varchar(255) not null, dni varchar(255), email varchar(255) not null unique, full_name varchar(255) not null, phone varchar(255), role varchar(255) not null, ruc varchar(255), first_name varchar(255), maternal_last_name varchar(255), paternal_last_name varchar(255));

create table connectify.events (
  id bigint generated by default as identity primary key, capacity integer, date timestamp(6), description varchar(1500), location varchar(255), price numeric(38,2), revenue double precision, status varchar(255), title varchar(255), organizer_id bigint references connectify.users(id), address varchar(255), approved_at timestamp(6), approved_by bigint references connectify.users(id), available_tickets integer, category varchar(255), city varchar(255), country varchar(255), created_at timestamp(6), end_time varchar(255), event_date timestamp(6), featured boolean, image_url varchar(255), rejection_reason varchar(1000), start_time varchar(255), ticket_price double precision, total_tickets integer, updated_at timestamp(6), approval_notes text, banner_image_url varchar(255), cancellation_reason text, cancelled_at timestamp(6), contact_email varchar(255), contact_phone varchar(255), cover_image_url varchar(255), custom_page_url varchar(255), designer_id bigint, end_date timestamp(6), featured_order integer, full_address varchar(255), gallery_images text, is_featured boolean, legal_document_url varchar(255), max_tickets_per_purchase integer, min_tickets_per_purchase integer, organizer_name varchar(255), published_at timestamp(6), rejected_at timestamp(6), short_description varchar(255), sold_out boolean, submitted_at timestamp(6), tags text, terms_accepted boolean, tickets_sold integer not null, rejected_by bigint references connectify.users(id), sold integer, category_id bigint references connectify.categories(id), gate_access_code varchar(255), gate_password varchar(255), design_enabled boolean not null, design_template varchar(40), organizer_email varchar(255)
);
create index ix_events_organizer_id on connectify.events(organizer_id);
create index ix_events_approved_by on connectify.events(approved_by);
create index ix_events_rejected_by on connectify.events(rejected_by);
create index ix_events_category_id on connectify.events(category_id);

create table connectify.events_design_template_backup_20260709 (id bigint not null, title varchar(255), design_template varchar(40));
create table connectify.client_favorites (id bigint generated by default as identity primary key, created_at timestamp(6) not null, client_id bigint not null references connectify.user_accounts(id), event_id bigint not null references connectify.events(id), unique (client_id, event_id));
create index ix_client_favorites_event_id on connectify.client_favorites(event_id);
create table connectify.event_admin_records (id bigint generated by default as identity primary key, created_at timestamp(6), description varchar(2000), type varchar(255), event_id bigint references connectify.events(id));
create index ix_event_admin_records_event_id on connectify.event_admin_records(event_id);

create table connectify.event_presentation_settings (
  id bigint generated by default as identity primary key, accent_color varchar(20), highlight_text varchar(500), primary_color varchar(20), show_gallery boolean not null, show_organizer boolean not null, updated_at timestamp(6), event_id bigint not null unique references connectify.events(id), agenda_text text, benefits_text text, content_focus varchar(20), cover_focus varchar(20), cover_image_url text, info_position varchar(20), show_agenda boolean not null, show_benefits boolean not null, show_sponsors boolean not null, sponsors_text text, thumbnail_image_url text, session_text text, show_media boolean not null, show_sessions boolean not null, show_stage_map boolean not null, spotify_url text, stage_text text, youtube_url text, background_image_url text, organizer_brand_name varchar(180), organizer_logo_url text, stage_image_url text, sponsor_logos_text text
);

create table connectify.internal_messages (id bigint generated by default as identity primary key, body varchar(3000) not null, created_at timestamp(6), priority varchar(255) not null, read_by_target boolean not null, sender_email varchar(255) not null, sender_name varchar(255) not null, sender_role varchar(255) not null, status varchar(255) not null, subject varchar(255) not null, target_role varchar(255) not null, type varchar(255) not null, updated_at timestamp(6), event_id bigint references connectify.events(id));
create index ix_internal_messages_event_id on connectify.internal_messages(event_id);
create table connectify.ticket_types (id bigint generated by default as identity primary key, active boolean not null, description varchar(800), name varchar(255) not null, price numeric(38,2) not null, quantity_available integer not null, quantity_sold integer not null, sales_end timestamp(6), sales_start timestamp(6), event_id bigint references connectify.events(id));
create index ix_ticket_types_event_id on connectify.ticket_types(event_id);

create table connectify.purchases (id bigint generated by default as identity primary key, amount double precision, created_at timestamp(6), payment_reference varchar(255), quantity integer, status varchar(255), event_id bigint references connectify.events(id), user_id bigint references connectify.users(id), payment_date timestamp(6), payment_method varchar(255), transaction_id varchar(255), updated_at timestamp(6), buyer_dni varchar(255), buyer_email varchar(255), buyer_first_name varchar(255), buyer_last_name varchar(255), buyer_phone varchar(255), service_fee numeric(38,2) not null, subtotal numeric(38,2) not null, total numeric(38,2) not null);
create index ix_purchases_event_id on connectify.purchases(event_id);
create index ix_purchases_user_id on connectify.purchases(user_id);

create table connectify.tickets (id bigint generated by default as identity primary key, created_at timestamp(6), qr_code varchar(500), event_id bigint references connectify.events(id), owner_id bigint references connectify.users(id), purchase_id bigint references connectify.purchases(id), status varchar(255), ticket_code varchar(255) unique, updated_at timestamp(6), validated_at timestamp(6), validated_by bigint, user_id bigint references connectify.users(id), attendee_email varchar(255) not null, attendee_name varchar(255) not null, code varchar(255) not null unique, generated_at timestamp(6), used boolean not null);
create index ix_tickets_event_id on connectify.tickets(event_id);
create index ix_tickets_owner_id on connectify.tickets(owner_id);
create index ix_tickets_purchase_id on connectify.tickets(purchase_id);
create index ix_tickets_user_id on connectify.tickets(user_id);

create table connectify.notifications (id bigint generated by default as identity primary key, created_at timestamp(6), message varchar(2000), is_read boolean not null, type varchar(255), user_id bigint references connectify.users(id));
create index ix_notifications_user_id on connectify.notifications(user_id);
create table connectify.shopping_carts (id bigint generated by default as identity primary key, created_at timestamp(6) not null, updated_at timestamp(6) not null, buyer_id bigint not null unique references connectify.user_accounts(id));
create table connectify.shopping_cart_items (id bigint generated by default as identity primary key, added_at timestamp(6) not null, quantity integer not null, unit_price numeric(14,2) not null, updated_at timestamp(6) not null, cart_id bigint not null references connectify.shopping_carts(id), event_id bigint not null references connectify.events(id), ticket_type_id bigint references connectify.ticket_types(id));
create index ix_shopping_cart_items_cart_id on connectify.shopping_cart_items(cart_id);
create index ix_shopping_cart_items_event_id on connectify.shopping_cart_items(event_id);
create index ix_shopping_cart_items_ticket_type_id on connectify.shopping_cart_items(ticket_type_id);
create table connectify.shopping_cart_consumptions (order_number varchar(50) primary key, applied_at timestamp(6) not null, buyer_email varchar(255) not null);

create table connectify.izipay_web_attempts (order_number varchar(50) primary key, amount numeric(14,2) not null, "authorization" text, billing_json text not null, buyer_email varchar(255) not null, created_at timestamp(6) not null, currency varchar(3) not null, fingerprint varchar(64) not null, gateway_reference varchar(100), merchant_code varchar(20) not null, review_reason varchar(255), service_fee numeric(14,2) not null, signed_payload_hash varchar(64), snapshot_json text not null, status varchar(20) not null, subtotal numeric(14,2) not null, transaction_id varchar(40) not null unique, verification_token_hash varchar(64) not null, verified_at timestamp(6), purchase_id bigint unique references connectify.purchases(id), payment_method varchar(20));
create index ix_izipay_web_buyer on connectify.izipay_web_attempts(buyer_email, status);

do $$
declare table_name text;
begin
  foreach table_name in array array['categories','users','user_accounts','events','events_design_template_backup_20260709','client_favorites','event_admin_records','event_presentation_settings','internal_messages','ticket_types','purchases','tickets','notifications','shopping_carts','shopping_cart_items','shopping_cart_consumptions','izipay_web_attempts'] loop
    execute format('alter table connectify.%I enable row level security', table_name);
  end loop;
end $$;

revoke all on schema connectify from anon, authenticated;
revoke all on all tables in schema connectify from anon, authenticated;
alter default privileges in schema connectify revoke all on tables from anon, authenticated;
alter default privileges in schema connectify revoke all on sequences from anon, authenticated;
